import{_ as n,C as i,o as r,c as a,a2 as e,E as s}from"./chunks/framework.BSaF8iZ6.js";const w=JSON.parse('{"title":"Joining Admin Discounts","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/join-product-discounts.md","filePath":"marketing/join-product-discounts.md","lastUpdated":1789411447000}'),l={name:"marketing/join-product-discounts.md"};function d(c,t,u,g,h,p){const o=i("ImagePopup");return r(),a("div",null,[t[0]||(t[0]=e('<h1 id="joining-admin-discounts" tabindex="-1">Joining Admin Discounts <a class="header-anchor" href="#joining-admin-discounts" aria-label="Permalink to &quot;Joining Admin Discounts&quot;">​</a></h1><div class="page-roles"><span class="role role--admin">Admin</span><span class="role role--seller">Seller</span></div><p>The admin can open a store product discount to sellers. Sellers who join, and are approved, get that discount on their own products. This lets you run store-wide sales that include seller products, while each seller chooses whether to take part.</p><p>A product discount you create in the admin panel doesn&#39;t lower the price of any seller&#39;s product unless that seller has joined it and been approved.</p><h2 id="open-a-discount-to-sellers" tabindex="-1">Open a discount to sellers <a class="header-anchor" href="#open-a-discount-to-sellers" aria-label="Permalink to &quot;Open a discount to sellers&quot;">​</a></h2><ol><li>In the admin panel, go to <strong>Marketing &gt;&gt; Promotions &gt;&gt; Catalog Rules</strong>.</li><li>Create a catalog rule, or click the edit icon on an existing one.</li><li>In <strong>Participating Sellers</strong>, check that <strong>Allow Sellers to Join</strong> is on. It is on by default for every catalog rule, so switch it off for rules sellers shouldn&#39;t join.</li><li>To add sellers yourself, choose them in <strong>Sellers</strong>. Sellers you add take part straight away.</li><li>Click <strong>Save Catalog Rule</strong>.</li></ol>',6)),s(o,{src:"/images/join-product-discounts/participating-sellers.png",alt:"The Participating Sellers section of a catalog rule"}),t[1]||(t[1]=e('<p>Removing a seller from <strong>Sellers</strong> withdraws them from the discount. Switching <strong>Allow Sellers to Join</strong> off stops the discount for every seller who joined.</p><h2 id="join-a-discount" tabindex="-1">Join a discount <a class="header-anchor" href="#join-a-discount" aria-label="Permalink to &quot;Join a discount&quot;">​</a></h2><ol><li>In the Seller Panel, go to <strong>Marketing &gt;&gt; Product Discounts</strong>.</li><li>Click <strong>Join Product Discounts</strong>.</li><li>To see a discount&#39;s conditions, amount and dates, click the view icon on its row.</li><li>Click <strong>Enroll</strong>.</li></ol>',3)),s(o,{src:"/images/join-product-discounts/join-list.png",alt:"The Join Product Discounts list in the Seller Panel"}),t[2]||(t[2]=e('<p>The <strong>Join Product Discounts</strong> button appears only when the admin allows joining and you have the <strong>Join</strong> permission. The list can include discounts that are switched off or out of date, so check their status and dates before you enroll.</p><p>You&#39;ll see <strong>Enrolled in the product discount successfully.</strong> To join several discounts at once, tick them and use <strong>Select Action &gt;&gt; Enroll</strong>.</p><p>The <strong>Participation</strong> badge shows where you stand:</p><table tabindex="0"><thead><tr><th>Badge</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Not Enrolled</strong></td><td>You haven&#39;t joined.</td></tr><tr><td><strong>Pending</strong></td><td>You joined and are waiting for the admin to approve.</td></tr><tr><td><strong>Approved</strong></td><td>The discount applies to your products.</td></tr><tr><td><strong>Disapproved</strong></td><td>The admin declined your request. Open the discount and click <strong>Enroll</strong> to ask again. A new request always waits for the admin.</td></tr></tbody></table>',4)),s(o,{src:"/images/join-product-discounts/join-view.png",alt:"The details of a store discount a seller can join"}),t[3]||(t[3]=e('<h3 id="what-joining-covers" tabindex="-1">What joining covers <a class="header-anchor" href="#what-joining-covers" aria-label="Permalink to &quot;What joining covers&quot;">​</a></h3><ul><li>You join with all of your own products that match the discount&#39;s conditions. You can&#39;t choose products one by one.</li><li>Catalog products you sell as your own aren&#39;t discounted.</li><li>To leave, click <strong>Withdraw</strong> on the discount&#39;s row, or use <strong>Select Action &gt;&gt; Withdraw</strong>.</li></ul><h2 id="approve-join-requests" tabindex="-1">Approve join requests <a class="header-anchor" href="#approve-join-requests" aria-label="Permalink to &quot;Approve join requests&quot;">​</a></h2><p><strong>Auto-Approve Join Requests</strong> in <a href="./../configuration/marketing">Marketing settings</a> is on by default, so requests are approved straight away. When you switch it off, requests wait for you.</p><ol><li>In the admin panel, go to <strong>Marketplace &gt;&gt; Marketing &gt;&gt; Joined Product Discounts</strong>.</li><li>On a request, click <strong>Approve</strong> or <strong>Disapprove</strong>.</li></ol>',5)),s(o,{src:"/images/join-product-discounts/joined-product-discounts.png",alt:"The Joined Product Discounts list in the admin panel"}),t[4]||(t[4]=e('<p>Each row shows the discount, the seller, the <strong>Join Status</strong>, whether the discount is active, its priority and its dates. To decide on several requests at once, tick them and use <strong>Select Action &gt;&gt; Update Status</strong>. You can also disapprove a seller who is already approved.</p><h2 id="emails" tabindex="-1">Emails <a class="header-anchor" href="#emails" aria-label="Permalink to &quot;Emails&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Email</th><th>Sent to</th><th>When</th></tr></thead><tbody><tr><td><strong>A seller joined your promotion</strong></td><td>Store admin</td><td>A seller asks to join, including when the request is approved automatically</td></tr><tr><td><strong>Your promotion join request was approved</strong></td><td>Seller</td><td>You approve the request</td></tr><tr><td><strong>Your promotion join request was declined</strong></td><td>Seller</td><td>You disapprove the request</td></tr></tbody></table><p>No email is sent when you add or remove sellers on the catalog rule, or when a seller withdraws.</p><h2 id="when-the-discount-applies" tabindex="-1">When the discount applies <a class="header-anchor" href="#when-the-discount-applies" aria-label="Permalink to &quot;When the discount applies&quot;">​</a></h2><p>A joined discount lowers a seller&#39;s prices only while all of these are true:</p><ul><li>joining is switched on in <a href="./../configuration/marketing">Marketing settings</a>;</li><li>the catalog rule still has <strong>Allow Sellers to Join</strong> on;</li><li>the seller&#39;s request is <strong>Approved</strong>;</li><li>the rule itself is active, in date, and matches the channel and customer group.</li></ul><p>Prices are updated in the background, so a change can take a little while to show. Switching joining off in Marketing settings doesn&#39;t update prices straight away: joined discounts stay until the store&#39;s daily price update, just after midnight.</p><p>For the seller&#39;s own discounts, see <a href="./product-discounts">Product Discounts</a>.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li>Team members need <strong>Product Discounts &gt;&gt; Join</strong>, with <strong>View</strong>, <strong>Enroll</strong> and <strong>Withdraw</strong> as needed.</li><li>Admins need <strong>Marketplace &gt;&gt; Marketing &gt;&gt; Joined Product Discounts</strong>, with <strong>Approve</strong> and <strong>Disapprove</strong>. <strong>Select Action &gt;&gt; Update Status</strong> needs <strong>Approve</strong>.</li></ul><p>When joining is switched off in Marketing settings, these permissions and menus are hidden.</p>',12))])}const _=n(l,[["render",d]]);export{w as __pageData,_ as default};
